            &[b"f", b"--json=1"],
            &[b"f", b"--json="],
            &[b"f", b"--top"],
            &[b"f", b"--top", b"--json"],
            &[b"f", b"--top", b"--", b"2"],
            &[b"f", b"--top", b"-1"],
            &[b"--"],
            &[b"--", b"f", b"--json"],
            &[b"f", b"--json", b"--"],
            &[b"f", b"--", b"--"],
            &[b"-5\n\n"],
            &[b"-5x"],
            &[b"f", b"-5"],
            &[b"-x.txt"],
            &[b"f", b"---"],
            &[b"f", b"--=x"],
            &[b"-h-x"],
            &[b"-h=x"],
            &[b"--help=x"],
            &[b"f", b"--top", b"0", b"-h"],
            &[],
            &[b"f", b"--bogus"],
        ] {
            assert!(is_usage(&run(args)), "{args:?}");
        }
    }

