    #[test]
    fn digit_table_matches_python() {
        let data = include_str!("../tests/data/py_props.txt");
        let mut expected = vec![false; 0x110000];
        for line in data.lines().filter(|l| l.starts_with("DIGIT ")) {
            let mut parts = line.split(' ').skip(1);
            let lo = u32::from_str_radix(parts.next().unwrap_or("0"), 16).unwrap_or(0);
            let hi = u32::from_str_radix(parts.next().unwrap_or("0"), 16).unwrap_or(0);
            for cp in lo..=hi {
                expected[cp as usize] = true;
            }
        }
        let mut diffs = Vec::new();
        for cp in 0..0x110000u32 {
            if let Some(c) = char::from_u32(cp) {
                if is_py_digit(c) != expected[cp as usize] {
                    diffs.push(cp);
                }
            }
        }
        assert!(diffs.is_empty(), "digit differences: {diffs:X?}");
    }
}

//! 단어 규칙 (계약 2절): 공백 분리 → 앞뒤 문장 부호 제거 → 소문자 → 빈 문자열 버림.

use std::collections::HashMap;

/// 단어 앞뒤에서 떼어 낼 문장 부호 (ASCII 32자 + “ ” ‘ ’ … ·)
pub const PUNCTUATION: &str = "!\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~\u{201C}\u{201D}\u{2018}\u{2019}\u{2026}\u{B7}";

/// Python 3.12 `str.split()`(인자 없음)의 공백 집합 (Py_UNICODE_ISSPACE, Unicode 15.0).
/// verify/gen_props.py 로 Python 에서 뽑은 표와 단위 테스트로 대조한다.
/// `char::is_whitespace` 와 달리 U+001C–U+001F 를 포함한다.
pub fn is_py_space(c: char) -> bool {
    matches!(
        c,
        '\u{9}'..='\u{D}'
            | '\u{1C}'..='\u{20}'
            | '\u{85}'
            | '\u{A0}'
            | '\u{1680}'
            | '\u{2000}'..='\u{200A}'
            | '\u{2028}'
            | '\u{2029}'
            | '\u{202F}'
            | '\u{205F}'
            | '\u{3000}'
    )
}

fn is_punct(c: char) -> bool {
    PUNCTUATION.contains(c)
}

/// Python 3.12(Unicode 15.0)에서는 `lower()` 로 바뀌지 않지만 이 Rust 툴체인의
/// `char::to_lowercase` 는 바꾸는 글자. 전 코드 포인트 비교(text::tests::lower_table_matches_python)로 확정했다.
const PY_LOWER_UNCHANGED: &[char] = &[];

/// Final_Sigma 판단에서 Python 3.12 와 이 Rust 툴체인의 글자 분류가 다른 글자와 Python 쪽 분류.
/// 전 코드 포인트 비교(text::tests::sigma_class_matches_python)로 확정했다.
const PY_SIGMA_CLASS_OVERRIDES: &[(char, SigmaClass)] = &[];

/// Final_Sigma 문맥에서의 글자 분류
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SigmaClass {
    /// Case_Ignorable: 건너뛴다
    Ignorable,
    /// Cased 이고 Case_Ignorable 이 아님
    Cased,
    /// 그 밖
    Other,
}

const CAPITAL_SIGMA: char = '\u{3A3}';
const SMALL_SIGMA: char = '\u{3C3}';
const FINAL_SIGMA: char = '\u{3C2}';

/// Rust 표준 라이브러리의 Final_Sigma 처리 결과를 관찰해 분류를 얻는다
/// (core 의 Cased/Case_Ignorable 표는 공개 API 가 아니다).
///   "cΣ" 가 ς 로 끝남   <=> Cased(c) && !Case_Ignorable(c)
///   "AcΣ" 가 ς 로 끝남  <=> Case_Ignorable(c) || Cased(c)
fn rust_sigma_class(c: char) -> SigmaClass {
    let mut probe = String::with_capacity(8);
    probe.push(c);
    probe.push(CAPITAL_SIGMA);
    if probe.to_lowercase().ends_with(FINAL_SIGMA) {
        return SigmaClass::Cased;
    }
    probe.clear();
    probe.push('A');
    probe.push(c);
    probe.push(CAPITAL_SIGMA);
    if probe.to_lowercase().ends_with(FINAL_SIGMA) {
        SigmaClass::Ignorable
    } else {
        SigmaClass::Other
    }
}

/// Python 3.12 기준의 Final_Sigma 분류
pub fn sigma_class(c: char) -> SigmaClass {
    match PY_SIGMA_CLASS_OVERRIDES.iter().find(|(o, _)| *o == c) {
        Some(&(_, class)) => class,
        None => rust_sigma_class(c),
    }
}

/// CPython `handle_capital_sigma` 와 같은 판단
fn is_final_sigma(chars: &[char], i: usize) -> bool {
    let mut j = i;
    let mut before = None;
    while j > 0 {
        j -= 1;
        let class = sigma_class(chars[j]);
        if class != SigmaClass::Ignorable {
            before = Some(class);
            break;
        }
    }
    if before != Some(SigmaClass::Cased) {
        return false;
    }
    for &c in &chars[i + 1..] {
        let class = sigma_class(c);
        if class != SigmaClass::Ignorable {
            return class != SigmaClass::Cased;
        }
    }
    true
}

/// 글자 하나의 Python `lower()` 결과 (Σ 제외)
fn push_lower_char(out: &mut String, c: char) {
    if PY_LOWER_UNCHANGED.contains(&c) {
        out.push(c);
    } else {
        out.extend(c.to_lowercase());
    }
}

/// Python 3.12 `str.lower()` 와 같은 결과
pub fn py_lower(word: &str) -> String {
    let mut out = String::with_capacity(word.len());
    if !word.contains(CAPITAL_SIGMA) {
        for c in word.chars() {
            push_lower_char(&mut out, c);
        }
        return out;
    }
    let chars: Vec<char> = word.chars().collect();
    for (i, &c) in chars.iter().enumerate() {
        if c == CAPITAL_SIGMA {
            out.push(if is_final_sigma(&chars, i) {
                FINAL_SIGMA
            } else {
                SMALL_SIGMA
            });
        } else {
            push_lower_char(&mut out, c);
        }
    }
    out
}

/// 기준 구현 tokenize
pub fn tokenize(text: &str) -> Vec<String> {
    text.split(is_py_space)
        .filter(|raw| !raw.is_empty())
        .map(|raw| py_lower(raw.trim_matches(is_punct)))
        .filter(|word| !word.is_empty())
        .collect()
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Report {
    pub total_words: usize,
    pub unique_words: usize,
    pub top: Vec<(String, u64)>,
}

/// 빈도 내림차순, 같은 빈도는 코드 포인트 오름차순(= UTF-8 바이트 순)으로 상위 top_n 개
pub fn count_words(words: &[String], top_n: usize) -> Report {
    let mut counter: HashMap<&str, u64> = HashMap::new();
    for word in words {
        *counter.entry(word.as_str()).or_insert(0) += 1;
    }
    let unique_words = counter.len();
    let mut ranked: Vec<(String, u64)> = counter
        .into_iter()
        .map(|(w, n)| (w.to_string(), n))
        .collect();
    ranked.sort_unstable_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    ranked.truncate(top_n);
    Report {
        total_words: words.len(),
        unique_words,
        top: ranked,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn toks(text: &str) -> Vec<String> {
        tokenize(text)
    }

    #[test]
    fn reference_examples() {
        assert_eq!(
            toks("\"Hello,\" Don't e-mail... RUST!"),
            ["hello", "don't", "e-mail", "rust"]
        );
        assert!(toks("!!! --- ...").is_empty());
        let words: Vec<String> = ["b", "a", "c", "b", "a", "c", "d"]
            .iter()
            .map(|s| s.to_string())
            .collect();
        let report = count_words(&words, 10);
        let top: Vec<(&str, u64)> = report.top.iter().map(|(w, n)| (w.as_str(), *n)).collect();
        assert_eq!(top, [("a", 2), ("b", 2), ("c", 2), ("d", 1)]);
    }

    #[test]
    fn r1_whitespace() {
        // 기대값: verify/probe_text.py 의 Python tokenize 결과
        assert_eq!(toks("a\u{1c}b a\u{1f}b"), ["a", "b", "a", "b"]);
        assert_eq!(toks("a\u{b}b"), ["a", "b"]);
        assert_eq!(toks("a\u{3000}b"), ["a", "b"]);
        assert_eq!(toks("a\u{85}b"), ["a", "b"]);
        assert_eq!(toks("a\u{200b}b"), ["a\u{200b}b"]);
        assert_eq!(toks("a\u{180e}b"), ["a\u{180e}b"]);
        assert_eq!(toks("a\u{feff}b"), ["a\u{feff}b"]);
        assert_eq!(toks("a\u{2028}b\u{2029}c\u{a0}d\u{202f}e"), ["a", "b", "c", "d", "e"]);
    }

    #[test]
    fn r2_lowercase_and_sigma() {
        // 기대값: verify/probe_text.py 의 Python 3.12.3 lower() 결과
        assert_eq!(py_lower("\u{130}"), "i\u{307}");
        assert_eq!(py_lower("ΑΣ"), "ας");
        assert_eq!(py_lower("Σ"), "σ");
        assert_eq!(py_lower("ΑΣΑ"), "ασα");
        assert_eq!(py_lower("ΑΣ'Β"), "ας'β");
        assert_eq!(py_lower("ΆΣ"), "άς");
        assert_eq!(py_lower("ΑΣ\u{301}"), "ας\u{301}");
        assert_eq!(py_lower("ΑΣΣ"), "ασς");
        assert_eq!(py_lower("'Σ"), "σ");
    }

    #[test]
    fn r10_bom_cr_nul() {
        assert_eq!(toks("\u{feff}hello hello"), ["\u{feff}hello", "hello"]);
        assert_eq!(toks("a\rb"), ["a", "b"]);
        assert_eq!(toks("a\0b"), ["a\0b"]);
    }

    #[test]
    fn r11_order_and_truncate() {
        let words = toks("é e z \u{fffd} \u{1f600} z");
        let report = count_words(&words, usize::MAX);
        let top: Vec<&str> = report.top.iter().map(|(w, _)| w.as_str()).collect();
        assert_eq!(top, ["z", "e", "é", "\u{fffd}", "\u{1f600}"]);
        assert_eq!(report.total_words, 6);
        assert_eq!(report.unique_words, 5);
    }

    struct Tables {
        lower: HashMap<u32, String>,
        classes: Vec<SigmaClass>,
        spaces: Vec<bool>,
    }

    fn hex(s: &str) -> u32 {
        u32::from_str_radix(s, 16).unwrap_or(u32::MAX)
    }

    fn load_tables() -> Tables {
        let lower_data = include_str!("../tests/data/py_lower_table.txt");
        let props_data = include_str!("../tests/data/py_props.txt");
        let mut lower = HashMap::new();
        let mut classes = vec![SigmaClass::Other; 0x110000];
        for line in lower_data.lines() {
            let parts: Vec<&str> = line.split(' ').collect();
            match parts.as_slice() {
                ["L", cp, seq] => {
                    let s: String = seq
                        .split(',')
                        .filter_map(|h| char::from_u32(hex(h)))
                        .collect();
                    lower.insert(hex(cp), s);
                }
                ["S", class, lo, hi] => {
                    let class = if *class == "C" {
                        SigmaClass::Cased
                    } else {
                        SigmaClass::Ignorable
                    };
                    for cp in hex(lo)..=hex(hi) {
                        classes[cp as usize] = class;
                    }
                }
                _ => {}
            }
        }
        let mut spaces = vec![false; 0x110000];
        for line in props_data.lines() {
            let parts: Vec<&str> = line.split(' ').collect();
            if let ["SPACE", lo, hi] = parts.as_slice() {
                for cp in hex(lo)..=hex(hi) {
                    spaces[cp as usize] = true;
                }
            }
        }
        Tables {
            lower,
            classes,
            spaces,
        }
    }

    #[test]
    fn rust_unicode_version_is_reported() {
        let (a, b, c) = char::UNICODE_VERSION;
        eprintln!("rust char::UNICODE_VERSION = {a}.{b}.{c}");
    }

    /// 위험 R2: 전 코드 포인트(서로게이트 제외)의 lower() 를 Python 3.12 표와 비교
    #[test]
    fn lower_table_matches_python() {
        let tables = load_tables();
        assert!(tables.lower.len() > 1000, "table not loaded");
        let mut diffs = Vec::new();
        for cp in 0..0x110000u32 {
            let Some(c) = char::from_u32(cp) else {
                continue;
            };
            if c == CAPITAL_SIGMA {
                continue;
            }
            let expected = tables.lower.get(&cp).cloned().unwrap_or_else(|| c.to_string());
            let mut got = String::new();
            push_lower_char(&mut got, c);
            if got != expected {
                let rust_raw: String = c.to_lowercase().collect();
                diffs.push(format!(
                    "U+{cp:04X} python={:X?} ours={:X?} rust_raw={:X?}",
                    expected.chars().map(u32::from).collect::<Vec<_>>(),
                    got.chars().map(u32::from).collect::<Vec<_>>(),
                    rust_raw.chars().map(u32::from).collect::<Vec<_>>()
                ));
            }
        }
        assert!(
            diffs.is_empty(),
            "{} lower differences:\n{}",
            diffs.len(),
            diffs.join("\n")
        );
    }

    /// 위험 R2: Final_Sigma 판단에 쓰는 글자 분류를 Python 3.12 와 비교
    #[test]
    fn sigma_class_matches_python() {
        let tables = load_tables();
        let mut diffs = Vec::new();
        for cp in 0..0x110000u32 {
            let Some(c) = char::from_u32(cp) else {
                continue;
            };
            let expected = tables.classes[cp as usize];
            let got = sigma_class(c);
            if got != expected {
                diffs.push(format!(
                    "U+{cp:04X} python={expected:?} ours={got:?} rust_raw={:?}",
                    rust_sigma_class(c)
                ));
            }
        }
        assert!(
            diffs.is_empty(),
            "{} sigma class differences:\n{}",
            diffs.len(),
            diffs.join("\n")
        );
    }

    /// 위험 R1: 공백 집합을 Python 3.12 와 비교
    #[test]
    fn space_table_matches_python() {
        let tables = load_tables();
        let mut diffs = Vec::new();
        for cp in 0..0x110000u32 {
            let Some(c) = char::from_u32(cp) else {
                continue;
            };
            if is_py_space(c) != tables.spaces[cp as usize] {
                diffs.push(format!("U+{cp:04X}"));
            }
        }
        assert!(diffs.is_empty(), "space differences: {}", diffs.join(" "));
    }
}

//! 정상 출력 (계약 3절): 텍스트 형식과 JSON 형식.

use crate::text::Report;
use std::fmt::Write as _;

/// `words: N\nunique: M\n<count>\t<word>\n...`
pub fn format_text(report: &Report) -> String {
    let mut out = String::new();
    let _ = writeln!(out, "words: {}", report.total_words);
    let _ = writeln!(out, "unique: {}", report.unique_words);
    for (word, count) in &report.top {
        let _ = writeln!(out, "{count}\t{word}");
    }
    out
}

/// Python `json.dumps(s, ensure_ascii=False)` 와 같은 문자열 이스케이프 (따옴표 포함)
pub fn json_string(out: &mut String, s: &str) {
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\u{8}' => out.push_str("\\b"),
            '\u{c}' => out.push_str("\\f"),
            c if u32::from(c) < 0x20 => {
                let _ = write!(out, "\\u{:04x}", u32::from(c));
            }
            c => out.push(c),
        }
    }
    out.push('"');
}

/// `{"words":N,"unique":M,"top":[{"word":"..","count":K},...]}\n`
pub fn format_json(report: &Report) -> String {
    let mut out = String::new();
    let _ = write!(
        out,
        "{{\"words\":{},\"unique\":{},\"top\":[",
        report.total_words, report.unique_words
    );
    for (i, (word, count)) in report.top.iter().enumerate() {
        if i > 0 {
            out.push(',');
        }
        out.push_str("{\"word\":");
        json_string(&mut out, word);
        let _ = write!(out, ",\"count\":{count}}}");
    }
    out.push_str("]}\n");
    out
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::text::{count_words, tokenize};

    fn json_for(text: &str) -> String {
        format_json(&count_words(&tokenize(text), 10))
    }

    #[test]
    fn r8_json_escapes() {
        // 기대값: verify/probe_text.py 의 Python json.dumps 결과
        assert_eq!(
            json_for("a\u{0}b"),
            "{\"words\":1,\"unique\":1,\"top\":[{\"word\":\"a\\u0000b\",\"count\":1}]}\n"
        );
        assert_eq!(
            json_for("a\u{8}b"),
            "{\"words\":1,\"unique\":1,\"top\":[{\"word\":\"a\\bb\",\"count\":1}]}\n"
        );
        assert_eq!(
            json_for("a\u{7f}b"),
            "{\"words\":1,\"unique\":1,\"top\":[{\"word\":\"a\u{7f}b\",\"count\":1}]}\n"
        );
        assert_eq!(
            json_for("a\"b"),
            "{\"words\":1,\"unique\":1,\"top\":[{\"word\":\"a\\\"b\",\"count\":1}]}\n"
        );
        assert_eq!(
            json_for("a\\b"),
            "{\"words\":1,\"unique\":1,\"top\":[{\"word\":\"a\\\\b\",\"count\":1}]}\n"
        );
        assert_eq!(
            json_for("a\u{200e}b"),
            "{\"words\":1,\"unique\":1,\"top\":[{\"word\":\"a\u{200e}b\",\"count\":1}]}\n"
        );
        assert_eq!(
            json_for("a\u{1b}b a\u{c}b"),
            "{\"words\":1,\"unique\":1,\"top\":[{\"word\":\"a\\u001bb\",\"count\":1}]}\n"
                .replace("\"words\":1", "\"words\":2")
                .replace(
                    "\"unique\":1,\"top\":[{\"word\":\"a\\u001bb\",\"count\":1}]",
                    "\"unique\":2,\"top\":[{\"word\":\"a\",\"count\":1},{\"word\":\"a\\u001bb\",\"count\":1},{\"word\":\"b\",\"count\":1}]"
                )
                .replace("\"words\":2", "\"words\":3")
        );
        assert_eq!(json_for(""), "{\"words\":0,\"unique\":0,\"top\":[]}\n");
        assert_eq!(
            json_for("러스트 러스트 rust"),
            "{\"words\":3,\"unique\":2,\"top\":[{\"word\":\"러스트\",\"count\":2},{\"word\":\"rust\",\"count\":1}]}\n"
        );
    }

    #[test]
    fn text_format() {
        let report = count_words(&tokenize("b a b"), 10);
        assert_eq!(format_text(&report), "words: 3\nunique: 2\n2\tb\n1\ta\n");
        let empty = count_words(&[], 10);
        assert_eq!(format_text(&empty), "words: 0\nunique: 0\n");
    }
}

//! wordfreq: 텍스트 파일의 단어 빈도를 센다 (python_src/wordfreq.py 2판의 Rust 이식).
//!
//! 동작 계약: contracts/behavior_spec.md
//! 출력은 모두 write_all + flush 결과를 확인한다. print!/println!/eprintln! 은 쓰지 않는다
//! (쓰기 실패 시 panic 하기 때문).

mod cli;
mod output;
mod text;

use std::ffi::OsString;
use std::io::{self, Write};
use std::path::{Path, PathBuf};
use std::process::ExitCode;

const EXIT_OK: u8 = 0;
const EXIT_INPUT_ERROR: u8 = 1;
const EXIT_USAGE_ERROR: u8 = 2;
const EXIT_OUTPUT_ERROR: u8 = 1;

/// stderr 에 쓴다. 실패는 무시한다 (stderr 가 닫혀 있어도 panic 하지 않음)
fn write_stderr(message: &str) {
    let mut err = io::stderr().lock();
    let _ = err.write_all(message.as_bytes());
    let _ = err.flush();
}

/// stdout 에 쓴다. 실패하면 false (계약 5절)
fn write_stdout(text: &str) -> bool {
    let mut out = io::stdout().lock();
    out.write_all(text.as_bytes()).is_ok() && out.flush().is_ok()
}

/// pathlib.Path(arg) 의 정규화를 흉내 낸다: 빈 성분·'.' 성분·끝의 '/' 를 없애고, 비면 '.'.
/// (Rust 는 맨 앞의 '.' 을 남기고 '//' 를 '/' 로 줄이지만 Linux 에서 여는 대상은 같다)
fn normalize(arg: &OsString) -> PathBuf {
    let path: PathBuf = Path::new(arg).components().collect();
    if path.as_os_str().is_empty() {
        PathBuf::from(".")
    } else {
        path
    }
}

enum ReadError {
    NotFound,
    NotUtf8,
    Other,
}

fn read_text(arg: &OsString) -> Result<String, ReadError> {
    let bytes = std::fs::read(normalize(arg)).map_err(|err| match err.kind() {
        io::ErrorKind::NotFound => ReadError::NotFound,
        _ => ReadError::Other,
    })?;
    String::from_utf8(bytes).map_err(|_| ReadError::NotUtf8)
}

fn run() -> u8 {
    let args: Vec<OsString> = std::env::args_os().skip(1).collect();
    let args = match cli::parse(&args) {
        cli::Outcome::Run(args) => args,
        cli::Outcome::Help => {
            // argparse 처럼 도움말 쓰기 실패는 무시하고 0
            let _ = write_stdout(cli::HELP);
            return EXIT_OK;
        }
        cli::Outcome::Usage(message) => {
            write_stderr(&format!("{}wordfreq: error: {message}\n", cli::USAGE));
            return EXIT_USAGE_ERROR;
        }
    };

    let name = cli::display_name(&args.file);
    let text = match read_text(&args.file) {
        Ok(text) => text,
        Err(ReadError::NotFound) => {
            write_stderr(&format!("wordfreq: error: file not found: {name}\n"));
            return EXIT_INPUT_ERROR;
        }
        Err(ReadError::NotUtf8) => {
            write_stderr(&format!("wordfreq: error: not valid UTF-8: {name}\n"));
            return EXIT_INPUT_ERROR;
        }
        Err(ReadError::Other) => {
            write_stderr(&format!("wordfreq: error: cannot read file: {name}\n"));
            return EXIT_INPUT_ERROR;
        }
    };

    let words = text::tokenize(&text);
    let report = text::count_words(&words, args.top);
    let rendered = if args.json {
        output::format_json(&report)
    } else {
        output::format_text(&report)
    };
    if !write_stdout(&rendered) {
        write_stderr("wordfreq: error: cannot write output\n");
        return EXIT_OUTPUT_ERROR;
    }
    EXIT_OK
}

fn main() -> ExitCode {
    ExitCode::from(run())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn r5_normalize_like_pathlib() {
        // 기대값: Python str(pathlib.Path(x)) (verify/probe_text.py 출력)
        let cases = [
            ("", "."),
            (".", "."),
            ("tests/fixtures/basic.txt/", "tests/fixtures/basic.txt"),
            ("tests/fixtures/basic.txt/.", "tests/fixtures/basic.txt"),
            ("tests/fixtures/./basic.txt", "tests/fixtures/basic.txt"),
            ("a//b", "a/b"),
            ("a/../b", "a/../b"),
        ];
        for (input, expected) in cases {
            assert_eq!(
                normalize(&OsString::from(input)),
                PathBuf::from(expected),
                "{input:?}"
            );
        }
        // pathlib 은 './a' 를 'a' 로 줄이고 Rust 는 './a' 로 남기지만 가리키는 파일은 같다
        assert_eq!(normalize(&OsString::from("./a")), PathBuf::from("./a"));
    }
}

