1	//! argparse(Python 3.12) 호환 명령행 파서.
2	//!
3	//! 기준 구현은 다음 파서를 쓴다.
4	//!
5	//! ```text
6	//! parser = argparse.ArgumentParser(prog="wordfreq", description="Count word frequencies.")
7	//! parser.add_argument("file")
8	//! parser.add_argument("--top", type=positive_int, default=10)
9	//! parser.add_argument("--json", action="store_true")
10	//! ```
11	//!
12	//! 이 모듈은 위 설정에 대해 `argparse._parse_known_args` 의 처리 순서를 그대로 따른다
13	//! (`--`, `-`, `--top=1`, 접두어 약어, 반복 시 마지막 값, 음수 모양 위치 인자, `-h` 묶음 등).
14	//! 인자는 바이트로 다루므로 UTF-8 이 아닌 인자에서도 panic 하지 않는다.
15	
16	use std::ffi::OsString;
17	
18	pub const USAGE: &str = "usage: wordfreq [-h] [--top TOP] [--json] file\n";
19	
20	pub const HELP: &str = "usage: wordfreq [-h] [--top TOP] [--json] file
21	
22	Count word frequencies.
23	
24	positional arguments:
25	  file        UTF-8 text file
26	
27	options:
28	  -h, --help  show this help message and exit
29	  --top TOP   number of words (default 10)
30	  --json      print JSON instead of text
31	";
32	
33	/// 기본 --top 값
34	const DEFAULT_TOP: usize = 10;
35	
36	/// positive_int 의 MAX_TOP_DIGITS. 이보다 자릿수가 많으면 "아주 큰 수"로 본다
37	const MAX_TOP_DIGITS: usize = 18;
38	
39	#[derive(Debug, Clone, PartialEq, Eq)]
40	pub struct Args {
41	    pub file: OsString,
42	    pub top: usize,
43	    pub json: bool,
44	}
45	
46	#[derive(Debug, Clone, PartialEq, Eq)]
47	pub enum Outcome {
48	    /// 정상 실행
49	    Run(Args),
50	    /// -h/--help: 도움말을 stdout 에 쓰고 0 으로 끝낸다
51	    Help,
52	    /// 인자 오류: stderr 에 사용법과 메시지를 쓰고 2 로 끝낸다 (메시지는 계약상 비교 안 함)
53	    Usage(String),
54	}
55	
56	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
57	enum Action {
58	    Help,
59	    Top,
60	    Json,
61	}
62	
63	impl Action {
64	    /// argparse 의 nargs: help·json 은 0, top 은 1
65	    fn nargs(self) -> usize {
66	        match self {
67	            Action::Help | Action::Json => 0,
68	            Action::Top => 1,
69	        }
70	    }
71	
72	    fn display(self) -> &'static str {
73	        match self {
74	            Action::Help => "-h/--help",
75	            Action::Top => "--top",
76	            Action::Json => "--json",
77	        }
78	    }
79	}
80	
81	/// `parser._option_string_actions` 의 삽입 순서
82	const OPTION_STRINGS: [(&[u8], Action); 4] = [
83	    (b"-h", Action::Help),
84	    (b"--help", Action::Help),
85	    (b"--top", Action::Top),
86	    (b"--json", Action::Json),
87	];
88	
89	fn lookup(option: &[u8]) -> Option<Action> {
90	    OPTION_STRINGS
91	        .iter()
92	        .find(|(name, _)| *name == option)
93	        .map(|(_, action)| *action)
94	}
95	
96	/// argparse 의 option tuple: (action, option_string, sep, explicit_arg)
97	#[derive(Debug, Clone, PartialEq, Eq)]
98	struct OptTuple {
99	    action: Option<Action>,
100	    option_string: Vec<u8>,
101	    /// None = 구분자 없음, Some(false) = '' (단일 대시 붙여 쓰기), Some(true) = '='
102	    sep_eq: Option<bool>,
103	    explicit: Option<Vec<u8>>,
104	}
105	
106	/// 패턴 문자: 'A' 위치 인자, 'O' 옵션, '-' 첫 번째 `--`
107	#[derive(Debug, Clone, PartialEq, Eq)]
108	enum Kind {
109	    Pos,
110	    Dash,
111	    Opt(OptTuple),
112	}
113	
114	impl Kind {
115	    fn code(&self) -> u8 {
116	        match self {
117	            Kind::Pos => b'A',
118	            Kind::Dash => b'-',
119	            Kind::Opt(_) => b'O',
120	        }
121	    }
122	}
123	
124	struct UsageError(String);
125	
126	fn lossy(bytes: &[u8]) -> String {
127	    String::from_utf8_lossy(bytes).into_owned()
128	}
129	
130	/// Python repr() 비슷한 따옴표 표기 (메시지용, 비교 대상 아님)
131	fn quoted(bytes: &[u8]) -> String {
132	    format!("'{}'", lossy(bytes))
133	}
134	
135	/// 인자의 원래 바이트. Unix 에서는 OS 가 준 바이트 그대로다
136	pub fn os_bytes(arg: &std::ffi::OsStr) -> Vec<u8> {
137	    #[cfg(unix)]
138	    {
139	        use std::os::unix::ffi::OsStrExt;
140	        arg.as_bytes().to_vec()
141	    }
142	    #[cfg(not(unix))]
143	    {
144	        arg.to_string_lossy().into_owned().into_bytes()
145	    }
146	}
147	
148	/// 오류 메시지에 넣을 이름: UTF-8 이 아닌 부분은 최대 부분마다 U+FFFD (계약 4절)
149	pub fn display_name(arg: &std::ffi::OsStr) -> String {
150	    lossy(&os_bytes(arg))
151	}
152	
153	/// Python 3.12 re 의 `\d`(str 패턴) 집합 = Unicode 15.0 의 Nd.
154	/// verify/gen_props.py 로 Python 에서 뽑았다 (rust_app/tests/data/py_props.txt 와 단위 테스트로 대조).
