222	pub fn is_py_digit(c: char) -> bool {
223	    let cp = u32::from(c);
224	    PY_DIGIT_RANGES.iter().any(|&(lo, hi)| lo <= cp && cp <= hi)
225	}
226	
227	/// `re.match(r'^-\d+$|^-\d*\.\d+$', s)`. `$` 는 끝 또는 마지막 '\n' 바로 앞에서 맞는다
228	fn looks_like_negative_number(arg: &[u8]) -> bool {
229	    let Ok(text) = std::str::from_utf8(arg) else {
230	        // UTF-8 이 아닌 바이트는 Python 에서 서로게이트 글자가 되어 어느 쪽에도 맞지 않는다
231	        return false;
232	    };
233	    let body = text.strip_suffix('\n').unwrap_or(text);
234	    let Some(rest) = body.strip_prefix('-') else {
235	        return false;
236	    };
237	    let all_digits = |s: &str| s.chars().all(is_py_digit);
238	    if !rest.is_empty() && all_digits(rest) {
239	        return true;
240	    }
241	    match rest.split_once('.') {
242	        Some((int_part, frac)) => !frac.is_empty() && all_digits(int_part) && all_digits(frac),
243	        None => false,
244	    }
245	}
246	
247	fn split_eq(arg: &[u8]) -> (&[u8], Option<&[u8]>) {
248	    match arg.iter().position(|&b| b == b'=') {
249	        Some(pos) => (&arg[..pos], Some(&arg[pos + 1..])),
250	        None => (arg, None),
251	    }
252	}
253	
254	/// argparse `_parse_optional`. Ok(None) 은 위치 인자
255	fn parse_optional(arg: &[u8]) -> Result<Option<OptTuple>, UsageError> {
256	    if arg.first() != Some(&b'-') {
257	        return Ok(None);
258	    }
259	    if let Some(action) = lookup(arg) {
260	        return Ok(Some(OptTuple {
261	            action: Some(action),
262	            option_string: arg.to_vec(),
263	            sep_eq: None,
264	            explicit: None,
265	        }));
266	    }
267	    if arg.len() == 1 {
268	        return Ok(None);
269	    }
270	    let (name, value) = split_eq(arg);
271	    if let Some(value) = value {
272	        if let Some(action) = lookup(name) {
273	            return Ok(Some(OptTuple {
274	                action: Some(action),
275	                option_string: name.to_vec(),
276	                sep_eq: Some(true),
277	                explicit: Some(value.to_vec()),
278	            }));
279	        }
280	    }
281	
282	    let tuples = option_tuples(arg);
283	    if tuples.len() > 1 {
284	        let names: Vec<String> = tuples.iter().map(|t| lossy(&t.option_string)).collect();
285	        return Err(UsageError(format!(
286	            "ambiguous option: {} could match {}",
287	            lossy(arg),
288	            names.join(", ")
289	        )));
290	    }
291	    if let Some(tuple) = tuples.into_iter().next() {
292	        return Ok(Some(tuple));
293	    }
294	    if looks_like_negative_number(arg) {
295	        return Ok(None);
296	    }
297	    if arg.contains(&b' ') {
298	        return Ok(None);
299	    }
300	    Ok(Some(OptTuple {
301	        action: None,
302	        option_string: arg.to_vec(),
303	        sep_eq: None,
304	        explicit: None,
305	    }))
306	}
307	
308	/// argparse `_get_option_tuples` (allow_abbrev=True). arg 는 '-' 로 시작하고 길이 2 이상
309	fn option_tuples(arg: &[u8]) -> Vec<OptTuple> {
310	    let mut result = Vec::new();
311	    if arg.get(1) == Some(&b'-') {
312	        let (prefix, value) = split_eq(arg);
313	        for (name, action) in OPTION_STRINGS {
314	            if name.starts_with(prefix) {
315	                result.push(OptTuple {
316	                    action: Some(action),
317	                    option_string: name.to_vec(),
318	                    sep_eq: value.map(|_| true),
319	                    explicit: value.map(<[u8]>::to_vec),
320	                });
321	            }
322	        }
323	    } else {
324	        // 단일 대시: 앞 두 글자가 옵션 이름과 같으면 나머지를 붙여 쓴 값으로 본다.
325	        // 옵션 이름이 모두 ASCII 이므로 바이트 비교로 충분하다
326	        let short = arg.get(..2);
327	        for (name, action) in OPTION_STRINGS {
328	            if Some(name) == short {
329	                result.push(OptTuple {
330	                    action: Some(action),
331	                    option_string: name.to_vec(),
332	                    sep_eq: Some(false),
333	                    explicit: Some(arg.get(2..).unwrap_or_default().to_vec()),
334	                });
335	            } else if name.starts_with(arg) {
336	                result.push(OptTuple {
337	                    action: Some(action),
338	                    option_string: name.to_vec(),
339	                    sep_eq: None,
340	                    explicit: None,
341	                });
342	            }
343	        }
344	    }
345	    result
346	}
