348	/// 첫 글자(UTF-8 한 글자, 깨진 바이트면 1바이트)의 길이
349	fn first_char_len(bytes: &[u8]) -> usize {
350	    match bytes.first() {
351	        None => 0,
352	        Some(&b) if b < 0x80 => 1,
353	        Some(_) => {
354	            let take = bytes.len().min(4);
355	            for n in (1..=take).rev() {
356	                if std::str::from_utf8(&bytes[..n]).is_ok() {
357	                    return n;
358	                }
359	            }
360	            1
361	        }
362	    }
363	}
