365	/// 계약 1절 / 기준 구현 positive_int
366	pub fn positive_int(value: &[u8]) -> Result<usize, String> {
367	    if value.is_empty() || !value.iter().all(u8::is_ascii_digit) {
368	        return Err(format!("not an integer: {}", lossy(value)));
369	    }
370	    let start = value.iter().position(|&b| b != b'0').unwrap_or(value.len());
371	    let digits = &value[start..];
372	    if digits.is_empty() {
373	        return Err(format!("must be at least 1: {}", lossy(value)));
374	    }
375	    if digits.len() > MAX_TOP_DIGITS {
376	        return Ok(usize::MAX);
377	    }
378	    let mut n: u64 = 0;
379	    for &d in digits {
380	        // 18자리 이하이므로 u64 에서 넘치지 않는다
381	        n = n * 10 + u64::from(d - b'0');
382	    }
383	    Ok(usize::try_from(n).unwrap_or(usize::MAX))
384	}
