386	struct State<'a> {
387	    args: &'a [OsString],
388	    raw: Vec<Vec<u8>>,
389	    kinds: Vec<Kind>,
390	    pattern: Vec<u8>,
391	    file: Option<OsString>,
392	    top: usize,
393	    json: bool,
394	    extras: Vec<Vec<u8>>,
395	}
396	
397	enum Stop {
398	    Help,
399	    Error(UsageError),
400	}
401	
402	impl From<UsageError> for Stop {
403	    fn from(err: UsageError) -> Self {
404	        Stop::Error(err)
405	    }
406	}
407	
408	impl State<'_> {
409	    /// `consume_positionals`: 위치 인자 file 의 패턴 '(-*A-*)'
410	    fn consume_positionals(&mut self, start: usize) -> usize {
411	        if self.file.is_some() {
412	            return start;
413	        }
414	        let rest = self.pattern.get(start..).unwrap_or_default();
415	        let mut i = 0;
416	        while rest.get(i) == Some(&b'-') {
417	            i += 1;
418	        }
419	        if rest.get(i) != Some(&b'A') {
420	            return start;
421	        }
422	        i += 1;
423	        while rest.get(i) == Some(&b'-') {
424	            i += 1;
425	        }
426	        // 인자 목록에서 첫 '--' 를 지운다 (_get_values 의 arg_strings.remove('--'))
427	        let mut taken: Vec<usize> = (start..start + i).collect();
428	        if let Some(pos) = taken.iter().position(|&k| self.raw[k] == b"--") {
429	            taken.remove(pos);
430	        }
431	        if let Some(&k) = taken.first() {
432	            self.file = Some(self.args[k].clone());
433	        }
434	        start + i
435	    }
436	
437	    /// `consume_optional`
438	    fn consume_optional(&mut self, start: usize) -> Result<usize, Stop> {
439	        let Kind::Opt(tuple) = self.kinds[start].clone() else {
440	            return Ok(start + 1);
441	        };
442	        let OptTuple {
443	            mut action,
444	            mut option_string,
445	            mut sep_eq,
446	            mut explicit,
447	        } = tuple;
448	        let mut action_tuples: Vec<(Action, Option<Vec<u8>>)> = Vec::new();
449	        let stop;
450	        loop {
451	            let Some(act) = action else {
452	                self.extras.push(self.raw[start].clone());
453	                return Ok(start + 1);
454	            };
455	            if let Some(exp) = explicit.take() {
456	                let arg_count = act.nargs();
457	                if arg_count == 0 && option_string.get(1) != Some(&b'-') && !exp.is_empty() {
458	                    if sep_eq == Some(true) || exp.first() == Some(&b'-') {
459	                        return Err(Stop::Error(UsageError(format!(
460	                            "argument {}: ignored explicit argument {}",
461	                            act.display(),
462	                            quoted(&exp)
463	                        ))));
464	                    }
465	                    action_tuples.push((act, None));
466	                    let n = first_char_len(&exp);
467	                    let mut next_option = vec![b'-'];
468	                    next_option.extend_from_slice(&exp[..n]);
469	                    if let Some(next) = lookup(&next_option) {
470	                        action = Some(next);
471	                        option_string = next_option;
472	                        let rest = &exp[n..];
473	                        if rest.is_empty() {
474	                            sep_eq = None;
475	                            explicit = None;
476	                        } else if rest[0] == b'=' {
477	                            sep_eq = Some(true);
478	                            explicit = Some(rest[1..].to_vec());
479	                        } else {
480	                            sep_eq = Some(false);
481	                            explicit = Some(rest.to_vec());
482	                        }
483	                    } else {
484	                        let mut extra = vec![b'-'];
485	                        extra.extend_from_slice(&exp);
486	                        self.extras.push(extra);
487	                        stop = start + 1;
488	                        break;
489	                    }
490	                } else if arg_count == 1 {
491	                    stop = start + 1;
492	                    action_tuples.push((act, Some(exp)));
493	                    break;
494	                } else {
495	                    return Err(Stop::Error(UsageError(format!(
496	                        "argument {}: ignored explicit argument {}",
497	                        act.display(),
498	                        quoted(&exp)
499	                    ))));
500	                }
501	            } else {
502	                let next = start + 1;
503	                let arg_count = act.nargs();
504	                if arg_count == 1 {
505	                    // 옵션의 패턴 '(A)': 바로 다음이 위치 인자여야 한다
506	                    if self.pattern.get(next) != Some(&b'A') {
507	                        return Err(Stop::Error(UsageError(format!(
508	                            "argument {}: expected one argument",
509	                            act.display()
510	                        ))));
511	                    }
512	                    action_tuples.push((act, Some(self.raw[next].clone())));
513	                } else {
514	                    action_tuples.push((act, None));
515	                }
516	                stop = next + arg_count;
517	                break;
518	            }
519	        }
520	        for (act, value) in action_tuples {
521	            match act {
522	                Action::Help => return Err(Stop::Help),
523	                Action::Json => self.json = true,
524	                Action::Top => {
525	                    let value = value.unwrap_or_default();
526	                    match positive_int(&value) {
527	                        Ok(n) => self.top = n,
528	                        Err(msg) => {
529	                            return Err(Stop::Error(UsageError(format!("argument --top: {msg}"))))
530	                        }
531	                    }
532	                }
533	            }
534	        }
535	        Ok(stop)
536	    }
537	}
