539	/// argv[1:] 를 해석한다
540	pub fn parse(args: &[OsString]) -> Outcome {
541	    match parse_inner(args) {
542	        Ok(parsed) => Outcome::Run(parsed),
543	        Err(Stop::Help) => Outcome::Help,
544	        Err(Stop::Error(UsageError(msg))) => Outcome::Usage(msg),
545	    }
546	}
547	
548	fn parse_inner(args: &[OsString]) -> Result<Args, Stop> {
549	    let raw: Vec<Vec<u8>> = args.iter().map(|a| os_bytes(a)).collect();
550	
551	    // 1단계: 각 인자를 'A' / 'O' / '-' 로 분류 (모호한 약어 오류는 여기서 바로 난다)
552	    let mut kinds = Vec::with_capacity(raw.len());
553	    let mut after_dashdash = false;
554	    for arg in &raw {
555	        if after_dashdash {
556	            kinds.push(Kind::Pos);
557	        } else if arg.as_slice() == b"--" {
558	            after_dashdash = true;
559	            kinds.push(Kind::Dash);
560	        } else {
561	            match parse_optional(arg)? {
562	                Some(tuple) => kinds.push(Kind::Opt(tuple)),
563	                None => kinds.push(Kind::Pos),
564	            }
565	        }
566	    }
567	    let pattern: Vec<u8> = kinds.iter().map(Kind::code).collect();
568	    let option_indices: Vec<usize> = kinds
569	        .iter()
570	        .enumerate()
571	        .filter(|(_, k)| matches!(k, Kind::Opt(_)))
572	        .map(|(i, _)| i)
573	        .collect();
574	
575	    let mut state = State {
576	        args,
577	        raw,
578	        kinds,
579	        pattern,
580	        file: None,
581	        top: DEFAULT_TOP,
582	        json: false,
583	        extras: Vec::new(),
584	    };
585	
586	    // 2단계: 위치 인자와 옵션을 번갈아 소비
587	    let mut start = 0usize;
588	    if let Some(&max_option) = option_indices.last() {
589	        while start <= max_option {
590	            let Some(&next_option) = option_indices.iter().find(|&&i| i >= start) else {
591	                break;
592	            };
593	            if start != next_option {
594	                let end = state.consume_positionals(start);
595	                if end > start {
596	                    start = end;
597	                    continue;
598	                }
599	                start = end;
600	            }
601	            if !option_indices.contains(&start) {
602	                for k in start..next_option {
603	                    let extra = state.raw[k].clone();
604	                    state.extras.push(extra);
605	                }
606	                start = next_option;
607	            }
608	            start = state.consume_optional(start)?;
609	        }
610	    }
611	    let stop = state.consume_positionals(start);
612	    for k in stop..state.raw.len() {
613	        let extra = state.raw[k].clone();
614	        state.extras.push(extra);
615	    }
616	
617	    let Some(file) = state.file else {
618	        return Err(Stop::Error(UsageError(
619	            "the following arguments are required: file".to_string(),
620	        )));
621	    };
622	    if !state.extras.is_empty() {
623	        let names: Vec<String> = state.extras.iter().map(|e| lossy(e)).collect();
624	        return Err(Stop::Error(UsageError(format!(
625	            "unrecognized arguments: {}",
626	            names.join(" ")
627	        ))));
628	    }
629	    Ok(Args {
630	        file,
631	        top: state.top,
632	        json: state.json,
633	    })
634	}
