1	//! wordfreq: 텍스트 파일의 단어 빈도를 센다 (python_src/wordfreq.py 2판의 Rust 이식).
2	//!
3	//! 동작 계약: contracts/behavior_spec.md
4	//! 출력은 모두 write_all + flush 결과를 확인한다. print!/println!/eprintln! 은 쓰지 않는다
5	//! (쓰기 실패 시 panic 하기 때문).
6	
7	mod cli;
8	mod output;
9	mod text;
10	
11	use std::ffi::OsString;
12	use std::io::{self, Write};
13	use std::path::{Path, PathBuf};
14	use std::process::ExitCode;
15	
16	const EXIT_OK: u8 = 0;
17	const EXIT_INPUT_ERROR: u8 = 1;
18	const EXIT_USAGE_ERROR: u8 = 2;
19	const EXIT_OUTPUT_ERROR: u8 = 1;
20	
21	/// stderr 에 쓴다. 실패는 무시한다 (stderr 가 닫혀 있어도 panic 하지 않음)
22	fn write_stderr(message: &str) {
23	    let mut err = io::stderr().lock();
24	    let _ = err.write_all(message.as_bytes());
25	    let _ = err.flush();
26	}
27	
28	/// stdout 에 쓴다. 실패하면 false (계약 5절)
29	fn write_stdout(text: &str) -> bool {
30	    let mut out = io::stdout().lock();
31	    out.write_all(text.as_bytes()).is_ok() && out.flush().is_ok()
32	}
33	
34	/// pathlib.Path(arg) 의 정규화를 흉내 낸다: 빈 성분·'.' 성분·끝의 '/' 를 없애고, 비면 '.'.
35	/// (Rust 는 맨 앞의 '.' 을 남기고 '//' 를 '/' 로 줄이지만 Linux 에서 여는 대상은 같다)
36	fn normalize(arg: &OsString) -> PathBuf {
37	    let path: PathBuf = Path::new(arg).components().collect();
38	    if path.as_os_str().is_empty() {
39	        PathBuf::from(".")
40	    } else {
41	        path
42	    }
43	}
44	
45	enum ReadError {
46	    NotFound,
47	    NotUtf8,
48	    Other,
49	}
50	
51	fn read_text(arg: &OsString) -> Result<String, ReadError> {
52	    let bytes = std::fs::read(normalize(arg)).map_err(|err| match err.kind() {
53	        io::ErrorKind::NotFound => ReadError::NotFound,
54	        _ => ReadError::Other,
55	    })?;
56	    String::from_utf8(bytes).map_err(|_| ReadError::NotUtf8)
57	}
58	
59	fn run() -> u8 {
60	    let args: Vec<OsString> = std::env::args_os().skip(1).collect();
61	    let args = match cli::parse(&args) {
62	        cli::Outcome::Run(args) => args,
63	        cli::Outcome::Help => {
64	            // argparse 처럼 도움말 쓰기 실패는 무시하고 0
65	            let _ = write_stdout(cli::HELP);
66	            return EXIT_OK;
67	        }
68	        cli::Outcome::Usage(message) => {
69	            write_stderr(&format!("{}wordfreq: error: {message}\n", cli::USAGE));
70	            return EXIT_USAGE_ERROR;
71	        }
72	    };
73	
74	    let name = cli::display_name(&args.file);
75	    let text = match read_text(&args.file) {
76	        Ok(text) => text,
77	        Err(ReadError::NotFound) => {
78	            write_stderr(&format!("wordfreq: error: file not found: {name}\n"));
79	            return EXIT_INPUT_ERROR;
80	        }
81	        Err(ReadError::NotUtf8) => {
82	            write_stderr(&format!("wordfreq: error: not valid UTF-8: {name}\n"));
83	            return EXIT_INPUT_ERROR;
84	        }
85	        Err(ReadError::Other) => {
86	            write_stderr(&format!("wordfreq: error: cannot read file: {name}\n"));
87	            return EXIT_INPUT_ERROR;
88	        }
89	    };
90	
91	    let words = text::tokenize(&text);
92	    let report = text::count_words(&words, args.top);
93	    let rendered = if args.json {
94	        output::format_json(&report)
95	    } else {
96	        output::format_text(&report)
97	    };
98	    if !write_stdout(&rendered) {
99	        write_stderr("wordfreq: error: cannot write output\n");
100	        return EXIT_OUTPUT_ERROR;
101	    }
102	    EXIT_OK
