98	/// Final_Sigma 문맥에서의 글자 분류
99	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
100	pub enum SigmaClass {
101	    /// Case_Ignorable: 건너뛴다
102	    Ignorable,
103	    /// Cased 이고 Case_Ignorable 이 아님
104	    Cased,
105	    /// 그 밖
106	    Other,
107	}
108	
109	const CAPITAL_SIGMA: char = '\u{3A3}';
110	const SMALL_SIGMA: char = '\u{3C3}';
111	const FINAL_SIGMA: char = '\u{3C2}';
112	
113	/// Rust 표준 라이브러리의 Final_Sigma 처리 결과를 관찰해 분류를 얻는다
114	/// (core 의 Cased/Case_Ignorable 표는 공개 API 가 아니다).
115	///   "cΣ" 가 ς 로 끝남   <=> Cased(c) && !Case_Ignorable(c)
116	///   "AcΣ" 가 ς 로 끝남  <=> Case_Ignorable(c) || Cased(c)
117	fn rust_sigma_class(c: char) -> SigmaClass {
118	    let mut probe = String::with_capacity(8);
119	    probe.push(c);
120	    probe.push(CAPITAL_SIGMA);
121	    if probe.to_lowercase().ends_with(FINAL_SIGMA) {
122	        return SigmaClass::Cased;
123	    }
124	    probe.clear();
125	    probe.push('A');
126	    probe.push(c);
127	    probe.push(CAPITAL_SIGMA);
128	    if probe.to_lowercase().ends_with(FINAL_SIGMA) {
129	        SigmaClass::Ignorable
130	    } else {
131	        SigmaClass::Other
132	    }
133	}
134	
135	/// Python 3.12 기준의 Final_Sigma 분류
136	pub fn sigma_class(c: char) -> SigmaClass {
137	    match PY_SIGMA_CLASS_OVERRIDES
138	        .iter()
139	        .find(|(lo, hi, _)| *lo <= c && c <= *hi)
140	    {
141	        Some(&(_, _, class)) => class,
142	        None => rust_sigma_class(c),
143	    }
144	}
145	
146	/// CPython `handle_capital_sigma` 와 같은 판단
147	fn is_final_sigma(chars: &[char], i: usize) -> bool {
148	    let mut j = i;
149	    let mut before = None;
150	    while j > 0 {
151	        j -= 1;
152	        let class = sigma_class(chars[j]);
153	        if class != SigmaClass::Ignorable {
154	            before = Some(class);
155	            break;
156	        }
157	    }
158	    if before != Some(SigmaClass::Cased) {
159	        return false;
160	    }
161	    for &c in &chars[i + 1..] {
162	        let class = sigma_class(c);
163	        if class != SigmaClass::Ignorable {
164	            return class != SigmaClass::Cased;
165	        }
166	    }
167	    true
168	}
