170	/// 글자 하나의 Python `lower()` 결과 (Σ 제외)
171	fn push_lower_char(out: &mut String, c: char) {
172	    if PY_LOWER_UNCHANGED
173	        .iter()
174	        .any(|&(lo, hi)| lo <= c && c <= hi)
175	    {
176	        out.push(c);
177	    } else {
178	        out.extend(c.to_lowercase());
179	    }
180	}
181	
182	/// Python 3.12 `str.lower()` 와 같은 결과
183	pub fn py_lower(word: &str) -> String {
184	    let mut out = String::with_capacity(word.len());
185	    if !word.contains(CAPITAL_SIGMA) {
186	        for c in word.chars() {
187	            push_lower_char(&mut out, c);
188	        }
189	        return out;
190	    }
191	    let chars: Vec<char> = word.chars().collect();
192	    for (i, &c) in chars.iter().enumerate() {
193	        if c == CAPITAL_SIGMA {
194	            out.push(if is_final_sigma(&chars, i) {
195	                FINAL_SIGMA
196	            } else {
197	                SMALL_SIGMA
198	            });
199	        } else {
200	            push_lower_char(&mut out, c);
201	        }
202	    }
203	    out
204	}
