206	/// 기준 구현 tokenize
207	pub fn tokenize(text: &str) -> Vec<String> {
208	    text.split(is_py_space)
209	        .filter(|raw| !raw.is_empty())
210	        .map(|raw| py_lower(raw.trim_matches(is_punct)))
211	        .filter(|word| !word.is_empty())
212	        .collect()
213	}
