215	#[derive(Debug, Clone, PartialEq, Eq)]
216	pub struct Report {
217	    pub total_words: usize,
218	    pub unique_words: usize,
219	    pub top: Vec<(String, u64)>,
220	}
221	
222	/// 빈도 내림차순, 같은 빈도는 코드 포인트 오름차순(= UTF-8 바이트 순)으로 상위 top_n 개
223	pub fn count_words(words: &[String], top_n: usize) -> Report {
224	    let mut counter: HashMap<&str, u64> = HashMap::new();
225	    for word in words {
226	        *counter.entry(word.as_str()).or_insert(0) += 1;
227	    }
228	    let unique_words = counter.len();
229	    let mut ranked: Vec<(String, u64)> = counter
230	        .into_iter()
231	        .map(|(w, n)| (w.to_string(), n))
232	        .collect();
233	    ranked.sort_unstable_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
234	    ranked.truncate(top_n);
235	    Report {
236	        total_words: words.len(),
237	        unique_words,
238	        top: ranked,
239	    }
240	}
