338	    fn load_tables() -> Tables {
339	        let lower_data = include_str!("../tests/data/py_lower_table.txt");
340	        let props_data = include_str!("../tests/data/py_props.txt");
341	        let mut lower = HashMap::new();
342	        let mut classes = vec![SigmaClass::Other; 0x110000];
343	        for line in lower_data.lines() {
344	            let parts: Vec<&str> = line.split(' ').collect();
345	            match parts.as_slice() {
346	                ["L", cp, seq] => {
347	                    let s: String = seq
348	                        .split(',')
349	                        .filter_map(|h| char::from_u32(hex(h)))
350	                        .collect();
351	                    lower.insert(hex(cp), s);
352	                }
353	                ["S", class, lo, hi] => {
354	                    let class = if *class == "C" {
355	                        SigmaClass::Cased
356	                    } else {
357	                        SigmaClass::Ignorable
358	                    };
359	                    for cp in hex(lo)..=hex(hi) {
360	                        classes[cp as usize] = class;
361	                    }
362	                }
363	                _ => {}
364	            }
365	        }
366	        let mut spaces = vec![false; 0x110000];
367	        for line in props_data.lines() {
368	            let parts: Vec<&str> = line.split(' ').collect();
369	            if let ["SPACE", lo, hi] = parts.as_slice() {
370	                for cp in hex(lo)..=hex(hi) {
371	                    spaces[cp as usize] = true;
372	                }
373	            }
374	        }
375	        Tables {
376	            lower,
377	            classes,
378	            spaces,
379	        }
380	    }
