3	use crate::text::Report;
4	use std::fmt::Write as _;
5	
6	/// `words: N\nunique: M\n<count>\t<word>\n...`
7	pub fn format_text(report: &Report) -> String {
8	    let mut out = String::new();
9	    let _ = writeln!(out, "words: {}", report.total_words);
10	    let _ = writeln!(out, "unique: {}", report.unique_words);
11	    for (word, count) in &report.top {
12	        let _ = writeln!(out, "{count}\t{word}");
13	    }
14	    out
15	}
16	
17	/// Python `json.dumps(s, ensure_ascii=False)` 와 같은 문자열 이스케이프 (따옴표 포함)
18	pub fn json_string(out: &mut String, s: &str) {
19	    out.push('"');
20	    for c in s.chars() {
21	        match c {
22	            '"' => out.push_str("\\\""),
23	            '\\' => out.push_str("\\\\"),
24	            '\n' => out.push_str("\\n"),
25	            '\r' => out.push_str("\\r"),
26	            '\t' => out.push_str("\\t"),
27	            '\u{8}' => out.push_str("\\b"),
28	            '\u{c}' => out.push_str("\\f"),
29	            c if u32::from(c) < 0x20 => {
30	                let _ = write!(out, "\\u{:04x}", u32::from(c));
31	            }
32	            c => out.push(c),
33	        }
34	    }
35	    out.push('"');
36	}
37	
38	/// `{"words":N,"unique":M,"top":[{"word":"..","count":K},...]}\n`
39	pub fn format_json(report: &Report) -> String {
40	    let mut out = String::new();
41	    let _ = write!(
42	        out,
43	        "{{\"words\":{},\"unique\":{},\"top\":[",
44	        report.total_words, report.unique_words
45	    );
46	    for (i, (word, count)) in report.top.iter().enumerate() {
47	        if i > 0 {
48	            out.push(',');
49	        }
50	        out.push_str("{\"word\":");
51	        json_string(&mut out, word);
52	        let _ = write!(out, ",\"count\":{count}}}");
53	    }
54	    out.push_str("]}\n");
55	    out
56	}
